@bosses[]   = roaming-boss-3(6-9, pump-man)
@bosses[]   = roaming-boss-4(10-9, wave-man)
@bosses[]   = roaming-boss-5(8-19, block-man)
#---------------------------#
@items[]   = boss-star-1(8-6, earth-star, concrete-man)
@items[]   = boss-star-2(8-12, impact-star, guts-man)
@items[]   = boss-star-3(6-9, water-star, pump-man)
@items[]   = boss-star-4(10-9, water-star, wave-man)
@items[]   = boss-star-5(8-19, earth-star, block-man)
#---------------------------#
@groups[]    = entrance-area(1-11, 2-11, 3-11, 2-10, 2-12)
@groups[]    = no-encounters(entrance-area)
